CREATE TABLE IF NOT EXISTS sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(80) NOT NULL, role VARCHAR(32) NOT NULL DEFAULT 'TEACHER', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS class_room (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, grade VARCHAR(32) NOT NULL, teacher_id BIGINT NOT NULL, is_demo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student (id BIGINT PRIMARY KEY AUTO_INCREMENT, class_id BIGINT NOT NULL, student_no VARCHAR(32) NOT NULL, name VARCHAR(80) NOT NULL, gender VARCHAR(16), status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', archived_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_student_no_class (class_id, student_no));
CREATE TABLE IF NOT EXISTS growth_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, dimension VARCHAR(16) NOT NULL, score DECIMAL(5,2) NOT NULL, title VARCHAR(160) NOT NULL, detail VARCHAR(500), occurred_on DATE NOT NULL, source VARCHAR(64) NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_growth_student_date (student_id, occurred_on));
CREATE TABLE IF NOT EXISTS score_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, subject VARCHAR(40) NOT NULL, exam_name VARCHAR(120) NOT NULL, score DECIMAL(6,2) NOT NULL, full_score DECIMAL(6,2) NOT NULL DEFAULT 100, occurred_on DATE NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_score_student_subject_date (student_id, subject, occurred_on));
CREATE TABLE IF NOT EXISTS attendance_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, attendance_date DATE NOT NULL, status VARCHAR(16) NOT NULL, note VARCHAR(200), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_attendance_student_date (student_id, attendance_date), INDEX idx_attendance_date (attendance_date));
CREATE TABLE IF NOT EXISTS behavior_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, category VARCHAR(40) NOT NULL, score DECIMAL(5,2), occurred_on DATE NOT NULL, detail VARCHAR(500), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_behavior_student_date (student_id, occurred_on));
CREATE TABLE IF NOT EXISTS skill_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, skill_name VARCHAR(120) NOT NULL, score DECIMAL(5,2) NOT NULL, level VARCHAR(32), occurred_on DATE NOT NULL, evidence VARCHAR(500), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_skill_student_date (student_id, occurred_on));
CREATE TABLE IF NOT EXISTS activity_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, activity_date DATE NOT NULL, activity_type VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PARTICIPATED', detail VARCHAR(300), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_activity_student_date (student_id, activity_date));
CREATE TABLE IF NOT EXISTS dimension_evaluation (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, moral_score DECIMAL(5,2), skill_score DECIMAL(5,2), thinking_score DECIMAL(5,2), smart_score DECIMAL(5,2), evidence VARCHAR(1000), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_dimension_student_period (student_id, period_start, period_end));
CREATE TABLE IF NOT EXISTS point_ledger (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, amount INT NOT NULL, category VARCHAR(40) NOT NULL, reason VARCHAR(160) NOT NULL, idempotency_key VARCHAR(120) NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_point_idempotency (idempotency_key));
CREATE TABLE IF NOT EXISTS point_rule (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL, amount INT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, description VARCHAR(300), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS warning_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, level VARCHAR(20) NOT NULL, rule_code VARCHAR(64) NOT NULL, summary VARCHAR(500) NOT NULL, evidence_json JSON NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', teacher_note VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, closed_at TIMESTAMP NULL, UNIQUE KEY uk_warning_window (student_id, rule_code, status));
CREATE TABLE IF NOT EXISTS intervention_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, warning_id BIGINT NULL, title VARCHAR(160) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', suggestions_json JSON NOT NULL, teacher_note VARCHAR(1000), review_at DATE NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS intervention_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, action VARCHAR(300) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DONE', occurred_on DATE NOT NULL, result VARCHAR(500), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS growth_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, module VARCHAR(30) NOT NULL, title VARCHAR(160) NOT NULL, description VARCHAR(500), due_on DATE NOT NULL, point_reward INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'PUBLISHED', created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, task_id BIGINT NOT NULL, student_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ASSIGNED', completed_on DATE NULL, teacher_note VARCHAR(500), UNIQUE KEY uk_student_task (task_id, student_id));
CREATE TABLE IF NOT EXISTS class_target (id BIGINT PRIMARY KEY AUTO_INCREMENT, class_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, target_value DECIMAL(8,2) NOT NULL, current_value DECIMAL(8,2) NOT NULL DEFAULT 0, unit VARCHAR(20), status VARCHAR(20) NOT NULL DEFAULT 'IN_PROGRESS', created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS class_diagnosis_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, target_id BIGINT NOT NULL, measure VARCHAR(500) NOT NULL, review_result VARCHAR(500), recorded_on DATE NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_diagnosis_target_date (target_id, recorded_on));
CREATE TABLE IF NOT EXISTS ai_analysis (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, source VARCHAR(20) NOT NULL, request_json JSON, response_json JSON NOT NULL, created_by BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_ai_student_date (student_id, created_at));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT NOT NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT NULL, summary VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
